const payload = items[0].json;
const input = payload.input ?? {};
const missingFields = [];
const invalidFields = [];
const allowedActions = new Set(['start_transaction', 'continue_transaction', 'validate_transaction', 'create_payment', 'create_order', 'issue_invoice', 'resolve_fulfillment', 'complete_transaction']);
function isNonEmptyString(value) { return typeof value === 'string' && value.trim().length > 0; }
